import{_ as t,o,c as a,a7 as r}from"./chunks/framework.C4ZIv4ii.js";const n="/falconcms/screenshots/wholesale-login.webp",s="/falconcms/screenshots/wholesale-portal.webp",i="/falconcms/screenshots/wholesale-quick-order.webp",d="/falconcms/screenshots/wholesale-portal-prices.webp",w=JSON.parse('{"title":"Login & Portal","description":"","frontmatter":{},"headers":[],"relativePath":"wholesale/portal.md","filePath":"wholesale/portal.md","lastUpdated":1792603034000}'),l={name:"wholesale/portal.md"};function h(c,e,p,g,u,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="login-portal" tabindex="-1">Login &amp; Portal <a class="header-anchor" href="#login-portal" aria-label="Permalink to &quot;Login &amp; Portal&quot;">​</a></h1><p>Wholesale customers have a sign-in page and a portal of their own. Both use the same customer accounts as the rest of the shop, so a trade buyer has one login for everything.</p><hr><h2 id="the-wholesale-login-page" tabindex="-1">The wholesale login page <a class="header-anchor" href="#the-wholesale-login-page" aria-label="Permalink to &quot;The wholesale login page&quot;">​</a></h2><p>Activating the plugin creates a page called <strong>Wholesale Login</strong> at <strong><code>/wholesale-login</code></strong>. It holds the <code>[falcon_wholesale_login]</code> shortcode.</p><p><img src="'+n+'" alt="The wholesale login page"></p><p><em>The login form takes your theme&#39;s colours. &quot;Apply for one&quot; leads to the application form.</em></p><ul><li>Edit it like any page: write what you like around the form, or change its address.</li><li>To use another page, pick it in <strong>Settings → Login page</strong>. Leave it on <em>Built-in screen</em> to use the plugin&#39;s own screen at <code>/wholesale/login</code>.</li><li>The form shares the CMS&#39;s <a href="/falconcms/guide/rbac.html#sign-in-lockout">sign-in lockout</a> <em>(FalconCMS 2.8.5+)</em>: five wrong passwords lock the account for 30 minutes, counted together with the dashboard and shop logins, so it cannot be used to guess an administrator&#39;s password.</li><li><strong><code>/wholesale/login</code></strong> always works: it forwards to the page you chose. Every &quot;please sign in&quot; link in the plugin goes there.</li><li>A page deleted by mistake comes back with <strong>Settings → Create the login page</strong>. Settings warns you when the chosen page is unpublished, in the trash, or lacks the shortcode.</li></ul><p>After signing in, a wholesale customer goes to their portal. A wholesale customer who opens the login page while signed in goes straight there too. Pages showing the form are kept out of the page cache and out of search.</p><h3 id="the-shortcode-on-any-page" tabindex="-1">The shortcode on any page <a class="header-anchor" href="#the-shortcode-on-any-page" aria-label="Permalink to &quot;The shortcode on any page&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[falcon_wholesale_login title=&quot;Trade login&quot; redirect=&quot;/wholesale/portal&quot; apply=&quot;no&quot;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>title</code></td><td>A heading in the card</td></tr><tr><td><code>redirect</code></td><td>Where to go after signing in. A <code>redirect_to</code> in the address wins.</td></tr><tr><td><code>apply=&quot;no&quot;</code></td><td>Hide &quot;No wholesale account yet? Apply for one&quot;</td></tr></tbody></table><p>A signed-in visitor sees a link to the portal (or to apply) instead of the form.</p><hr><h2 id="the-portal" tabindex="-1">The portal <a class="header-anchor" href="#the-portal" aria-label="Permalink to &quot;The portal&quot;">​</a></h2><p><strong><code>/wholesale/portal</code></strong> is the customer&#39;s home. It shows their company, their level, and <strong>Shop</strong> and <strong>Cart</strong> buttons, with tabs for everything else.</p><p><img src="'+s+'" alt="The wholesale portal overview"></p><p><em>The overview: orders, spending this month and in total, the customer&#39;s discount, and recent orders with Invoice and Order again.</em></p><table tabindex="0"><thead><tr><th>Tab</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Number of orders, spending this month and in total, their discount and minimum order, recent orders</td></tr><tr><td><strong>Quick order</strong></td><td>Order many products at once; see below</td></tr><tr><td><strong>Account &amp; invoices</strong></td><td>For customers who buy on account: what they owe, available credit, overdue amounts, unpaid invoices with due dates, and their statement</td></tr><tr><td><strong>Orders</strong></td><td>Every order, with its PO number and status, <strong>Invoice</strong>, and <strong>Order again</strong> (back into the cart at today&#39;s prices)</td></tr><tr><td><strong>Saved lists</strong></td><td>The company&#39;s saved carts, with Add to cart and reorder reminders</td></tr><tr><td><strong>Price list</strong></td><td>Every product they can buy, with retail, their price and the rules (minimum, pack), and <strong>Download CSV</strong></td></tr><tr><td><strong>Company</strong></td><td>Company details they can update, and the company&#39;s delivery addresses</td></tr><tr><td><strong>Team</strong></td><td>Owners and managers: invite, change and remove the people who buy for the company, and set who needs approval</td></tr><tr><td><strong>Approvals</strong></td><td>Owners and managers: orders waiting for approval, with Approve and Decline</td></tr><tr><td><strong>Quotes</strong></td><td>Quotes asked for and received, with Accept and Decline</td></tr></tbody></table><p>Tabs appear only when they apply: <em>Account &amp; invoices</em> only for credit customers, <em>Team</em> and <em>Approvals</em> only for owners and managers, <em>Quotes</em> only when quotes are on.</p><h3 id="quick-order" tabindex="-1">Quick order <a class="header-anchor" href="#quick-order" aria-label="Permalink to &quot;Quick order&quot;">​</a></h3><p>For customers who know what they want, <strong>Quick order</strong> puts many lines into the cart at once.</p><p><img src="'+i+'" alt="The quick order tab in the wholesale portal"></p><p><em>Quantities in a table, pasted SKUs, or a CSV upload — any mix goes into the cart together.</em></p><p>Three ways, in any mix:</p><ul><li><strong>The table</strong> — every product and variation they can buy, searchable by name or SKU, with their price and a quantity box.</li><li><strong>Paste SKUs</strong> — one line each: SKU and quantity, such as <code>RICE-50, 20</code>.</li><li><strong>Upload a CSV</strong> — columns <code>sku</code> and <code>quantity</code>.</li></ul><p><strong>Add to cart</strong> applies the same checks as the product page (they can see it, minimum quantity, pack size). Anything left out is listed with the reason.</p><h3 id="price-list" tabindex="-1">Price list <a class="header-anchor" href="#price-list" aria-label="Permalink to &quot;Price list&quot;">​</a></h3><p><img src="'+d+'" alt="The price list tab in the wholesale portal"></p><p><em>The customer&#39;s own prices next to retail, with each product&#39;s ordering rules, and a CSV download.</em></p><hr><h2 id="invoices-and-delivery-challans" tabindex="-1">Invoices and delivery challans <a class="header-anchor" href="#invoices-and-delivery-challans" aria-label="Permalink to &quot;Invoices and delivery challans&quot;">​</a></h2><p>Every order has a printable <strong>invoice</strong> and <strong>delivery challan</strong>:</p><ul><li><code>/wholesale/orders/{id}/invoice</code>, or <code>?type=challan</code> for the challan;</li><li>linked from the portal&#39;s order list and the admin order screen.</li></ul><p>They show your logo, address and <strong>BIN / VAT number</strong>, the customer&#39;s company and BIN, the PO number, the due date and amount due, any tax-exemption certificate, and your <strong>invoice footer</strong> (bank details, say). Set your BIN and the footer in <strong>Settings</strong>.</p><p>Print it, or save it as PDF from the browser&#39;s print dialog. Customers can open their own orders&#39; documents; staff can open anyone&#39;s.</p><hr><h2 id="private-store" tabindex="-1">Private store <a class="header-anchor" href="#private-store" aria-label="Permalink to &quot;Private store&quot;">​</a></h2><p><strong>Settings → Private store</strong> closes the whole storefront:</p><table tabindex="0"><thead><tr><th>Option</th><th>Who can browse the shop</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td>Everyone</td></tr><tr><td><strong>Signed-in customers only</strong></td><td>Any signed-in customer</td></tr><tr><td><strong>Approved wholesale customers only</strong></td><td>Trade buyers only</td></tr></tbody></table><p>Everyone else is sent to the wholesale login page. The login, application and My Account pages stay open, and so does the admin.</p>',41)])])}const b=t(l,[["render",h]]);export{w as __pageData,b as default};
